<script setup lang="ts">
import { computed } from 'vue'
import { ArrowRight, Bike, Check, Clock3, Flag, Footprints, MapPin, Sparkles } from 'lucide-vue-next'
import type { CulturalPlace, Journey, TourRoute } from '../types'
const props = defineProps<{ route: TourRoute; stops: CulturalPlace[]; journey?: Journey; selectedPlaceId: string }>()
const emit = defineEmits<{ selectPlace: [id: string]; start: []; complete: [] }>()
const completedCount = computed(() => props.journey?.completedStopIds.length ?? 0)
const finished = computed(() => completedCount.value === props.stops.length && props.stops.length > 0)
const nextStop = computed(() => props.stops.find(place => !props.journey?.completedStopIds.includes(place.id)))
</script>

<template>
  <article class="route-detail">
    <div class="route-cover"><Bike v-if="route.scene === 'rickshaw'" :size="39" :stroke-width="1.3" /><Footprints v-else :size="39" :stroke-width="1.3" /><span>{{ route.tag }}</span><h2>{{ route.title }}</h2><p>{{ route.subtitle }}</p><div class="route-facts"><span><Clock3 :size="14" />{{ route.duration }} 分钟</span><span><MapPin :size="14" />{{ route.distance }}</span><span><Flag :size="14" />{{ stops.length }} 站</span></div></div>
    <p class="route-description">{{ route.description }}</p>
    <div v-if="journey" class="progress-card"><div><strong>{{ finished ? '这一程，已珍藏' : '您的游览进度' }}</strong><span>{{ completedCount }} / {{ stops.length }} 站</span></div><progress :value="completedCount" :max="stops.length" :aria-label="`已完成 ${completedCount} 个地点`" /><p>{{ finished ? '湖岸与街巷的故事，已留在您的足迹里。' : `接下来：${nextStop?.name}` }}</p></div>
    <div class="itinerary-heading"><h3>这一程，怎么走</h3><span>预设游览顺序</span></div>
    <ol class="itinerary"><li v-for="(stop, index) in stops" :key="stop.id" :class="{ selected: selectedPlaceId === stop.id, complete: journey?.completedStopIds.includes(stop.id) }"><button @click="emit('selectPlace', stop.id)"><span class="stop-number"><Check v-if="journey?.completedStopIds.includes(stop.id)" :size="14" /><template v-else>{{ String(index + 1).padStart(2, '0') }}</template></span><span class="stop-copy"><strong>{{ stop.name }}</strong><small>{{ stop.category }} · {{ stop.duration }} 分钟讲解</small></span><ArrowRight :size="14" /></button></li></ol>
    <div class="transport-note"><Bike :size="17" /><p>{{ route.transportNote }}</p></div>
    <p v-if="route.scene === 'rickshaw'" class="route-disclaimer">图上连线为游览示意，非实时导航。实际通行及停靠请听从现场安排。</p>
    <div class="journey-actions"><button v-if="!journey" class="primary-button" @click="emit('start')">{{ route.scene === 'rickshaw' ? '开启这段慢游' : '开始场馆探索' }}<ArrowRight :size="16" /></button><template v-else-if="!finished"><button v-if="selectedPlaceId === nextStop?.id" class="primary-button" @click="emit('complete')"><Check :size="16" />完成本站，前往下一站</button><button v-else class="primary-button" @click="emit('start')">继续游览 · {{ nextStop?.name }}<ArrowRight :size="16" /></button><small>体验模式 · 手动确认游览进度</small></template><div v-else class="finished-message"><Sparkles :size="19" /><span>已完成全部 {{ stops.length }} 站，去「我的足迹」回看</span></div></div>
  </article>
</template>

<style scoped>
