op:6px}.itinerary button>svg{margin-left:auto;color:#9ca99d}.transport-note{display:flex;gap:10px;align-items:flex-start;padding:14px;background:#f5f3e9;border-radius:10px;color:#8d7c50;margin-top:20px}.transport-note>svg{flex-shrink:0;margin-top:3px}.transport-note p{font-size:11px;line-height:1.8;margin:0}.route-disclaimer{font-size:10px;color:var(--muted);line-height:1.8}.journey-actions{margin-top:24px}.journey-actions small{display:block;text-align:center;font-size:10px;margin-top:10px;color:var(--muted)}.finished-message{display:flex;align-items:center;gap:10px;padding:16px;background:#e6eee3;border-radius:10px;color:var(--lake);font-size:12px;line-height:1.7}
</style>
